Cypher query: MATCH (a:Article)
WHERE
  any(t IN [coalesce(a.name, '')] + coalesce(a.aliases, []) WHERE
    toLower(t) CONTAINS 'sony' AND
    toLower(t) CONTAINS 'music' AND
    (toLower(t) CONTAINS 'ai' OR toLower(t) CONTAINS 'artificial intelligence')
  )
  OR
  any(t IN [coalesce(a.name, '')] + coalesce(a.aliases, []) WHERE
    toLower(t) CONTAINS 'warner' AND
    toLower(t) CONTAINS 'music' AND
    (toLower(t) CONTAINS 'technology' OR toLower(t) CONTAINS 'tech') AND
    (toLower(t) CONTAINS 'creative' OR toLower(t) CONTAINS 'development')
  )
CALL {
  WITH a
  OPTIONAL MATCH (a)-[pr:MENTIONS|SAID|PARTICIPATED_IN]->(p:Person)
  RETURN collect(DISTINCT CASE WHEN p IS NOT NULL THEN {person: p.name, relationship: type(pr)} END) AS people
}
CALL {
  WITH a
  OPTIONAL MATCH (a)-[cr:MENTIONS|PART_OF|SAID]->(c)
  WHERE any(t IN [coalesce(c.name, '')] + coalesce(c.aliases, []) WHERE
    toLower(t) CONTAINS 'creativ' OR toLower(t) CONTAINS 'opportunit'
  )
  RETURN collect(DISTINCT CASE WHEN c IS NOT NULL THEN {claim: c.name, relationship: type(cr)} END) AS claims
}
RETURN a.name AS article_title, a.published_on AS published_on, people, claims
LIMIT 10
