  )
  AND (
    title CONTAINS 'inter miami'
    OR any(alias IN coalesce(a.aliases, []) WHERE toLower(alias) CONTAINS 'inter miami')
  )
  AND (
    (
      (d CONTAINS '2023-10-04' OR d CONTAINS 'october 4, 2023' OR d CONTAINS 'oct 4, 2023')
