        title CONTAINS 'ticket' OR title CONTAINS 'price'
        OR any(alias IN coalesce(a.aliases, []) WHERE toLower(alias) CONTAINS 'ticket' OR toLower(alias) CONTAINS 'price')
      )
    )
    OR
    (
      (d CONTAINS '2023-10-07' OR d CONTAINS 'october 7, 2023' OR d CONTAINS 'oct 7, 2023')
